function* unfold(seed, step) {        // step: S -> [value, nextSeed] | null
  let s = seed;
  while (s !== null) {
    const r = step(s);
    if (!r) return;                   // stop condition
    yield r[0];                       // one layer per next()
    s = r[1];                         // next seed
  }
}
// [...unfold(3, n => (n > 0 ? [n, n - 1] : null))]  ->  [3, 2, 1]
